import { _decorator, Color, Component, Graphics } from 'cc';
import { GRID_COLS, GRID_ORIGIN_X, GRID_ORIGIN_Y, GRID_ROWS, GRID_SIZE } from '../Config/GridConfig';
import type { EntityView } from '../../Engine/ViewRegistry';
import type { Entity } from '../../Engine/Entity';

const { ccclass } = _decorator;

@ccclass('GridView')
export class GridView extends Component implements EntityView {

   

    bind(entity: Entity): void {
        
    }

    sync(dt: number): void {
        
    }

    unbind(): void {
        
    }

    onLoad() {
        const g = this.node.addComponent(Graphics);
        g.lineWidth = 2;
        g.strokeColor = new Color(70, 70, 70, 255);

        // 竖线
        for (let c = 0; c <= GRID_COLS; c++) {
            const x = GRID_ORIGIN_X + c * GRID_SIZE;
            g.moveTo(x, GRID_ORIGIN_Y);
            g.lineTo(x, GRID_ORIGIN_Y + GRID_ROWS * GRID_SIZE);
        }
        // 横线
        for (let r = 0; r <= GRID_ROWS; r++) {
            const y = GRID_ORIGIN_Y + r * GRID_SIZE;
            g.moveTo(GRID_ORIGIN_X, y);
            g.lineTo(GRID_ORIGIN_X + GRID_COLS * GRID_SIZE, y);
        }
        g.stroke();
    }
}